style.css:
/* Analog Dreams — BandLab Studio Edition */

:root {
  /* puedes cambiar estos colores */
  --my-bg: #171513;
  --my-panel: #24201c;
  --my-panel-light: #302923;
  --my-cream: #e8ddc9;
  --my-muted: #aa9b83;
  --my-wine: #92515b;
  --my-wine-light: #b9757d;
  --my-olive: #858267;
  --my-shadow: 0 10px 30px rgba(0,0,0,.35);
  --my-inset: inset 0 1px 0 rgba(255,255,255,.07);
}

/* fondo general */
html, body {
  background: var(--my-bg) !important;
  color: var(--my-cream) !important;
  font-family: Georgia, serif !important;
}

/* paneles y superficies */
main, section, aside,
[role="dialog"], [role="tabpanel"] {
  box-shadow: var(--my-shadow), var(--my-inset) !important;
  border-radius: 12px !important;
}

/* botones elegantes */
button {
  border-radius: 9px !important;
  box-shadow: 0 4px 10px rgba(0,0,0,.28),
              inset 0 1px 0 rgba(255,255,255,.08) !important;
  transition: background .2s ease, box-shadow .2s ease !important;
}

/* efecto al pasar el cursor */
button:hover {
  filter: brightness(1.15) !important;
  box-shadow: 0 6px 16px rgba(0,0,0,.4) !important;
}

/* campos de texto */
input, textarea {
  background: var(--my-panel) !important;
  color: var(--my-cream) !important;
  border: 1px solid #514237 !important;
  border-radius: 8px !important;
  box-shadow: var(--my-inset) !important;
}

/* enlaces */
a {
  color: var(--my-wine-light) !important;
}

/* imágenes y portadas */
img {
  border-radius: 7px !important;
}

/* paneles oscuros */
[role="dialog"], [role="tabpanel"] {
  background-color: var(--my-panel) !important;
  border: 1px solid rgba(185,117,125,.16) !important;
}

/* detalles vintage */
hr {
  border-color: rgba(232,221,201,.13) !important;
}

/* selección de texto */
::selection {
  background: var(--my-wine) !important;
  color: white !important;
}
